import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, TurnUsage} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {ToolRegistry} from './tools/registry.js';

const promptBuilder = new PromptBuilder({identity: 'test'});
const session = (): ChatSession => ({
  sessionId: 's',
  userId: 'u',
  entries: [{role: 'user', content: 'c', timestamp: '2026-01-01T00:00:00Z'}],
});

function createMockProvider(rounds: MessageChunk[][]): AIProvider {
  let round = 0;
  return {
    async *sendMessage() {
      yield* rounds[round++] ?? [];
    },
    async generateStructured<T>() {
      return {} as T;
    },
  };
}

describe('ChatOrchestrator usage aggregation', () => {
  it('sums usage from multiple rounds', async () => {
    let reportedUsage: TurnUsage | undefined;
    const hooks = {
      afterModelResponse: async (_s: ChatSession, _t: string, usage?: TurnUsage) => {
        reportedUsage = usage;
      },
    };

    const registry = new ToolRegistry();
    registry.register({name: 'lookup', description: 'd', inputSchema: {type: 'object'}}, async () => 'r');

    const orchestrator = createChatOrchestrator(
      createMockProvider([
        [
          {type: 'tool_use', toolCall: {id: '1', name: 'lookup', input: {}}},
          {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 5, totalTokens: 15}},
        ],
        [
          {type: 'text', text: 'Done'},
          {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 20, outputTokens: 10, totalTokens: 30}},
        ],
      ]),
      promptBuilder,
      registry,
      {hooks}
    );

    await orchestrator.processMessage(session());

    expect(reportedUsage).toEqual({inputTokens: 30, outputTokens: 15, totalTokens: 45});
  });

  it('counts reported rounds while leaving a turn with no reported usage undefined', async () => {
    const reports: Array<TurnUsage | undefined> = [];
    const hooks = {
      afterModelResponse: async (_s: ChatSession, _t: string, usage?: TurnUsage) => {
        reports.push(usage);
      },
    };

    const registry = new ToolRegistry();
    registry.register({name: 'lookup', description: 'd', inputSchema: {type: 'object'}}, async () => 'r');

    const withGaps = createChatOrchestrator(
      createMockProvider([
        [
          {type: 'tool_use', toolCall: {id: '1', name: 'lookup', input: {}}},
          {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 2, outputTokens: 1, totalTokens: 3}},
        ],
        [{type: 'tool_use', toolCall: {id: '2', name: 'lookup', input: {}}}, {type: 'stop', stopReason: 'tool_use'}],
        [
          {type: 'text', text: 'Done'},
          {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 7, outputTokens: 4, totalTokens: 11}},
        ],
      ]),
      promptBuilder,
      registry,
      {hooks}
    );

    const withoutUsage = createChatOrchestrator(
      createMockProvider([[{type: 'text', text: 'Done'}, {type: 'stop', stopReason: 'end_turn'}]]),
      promptBuilder,
      undefined,
      {hooks}
    );

    await withGaps.processMessage(session());
    await withoutUsage.processMessage(session());

    expect(reports).toEqual([{inputTokens: 9, outputTokens: 5, totalTokens: 14}, undefined]);
  });
});

